// 1. ตรวจสอบ HTTP Status Code ต้องเป็น 200 OK
pm.test("[Status] Page loads successfully (200 OK)", function () {
    pm.response.to.have.status(200);
});

// 2. ตรวจสอบ Response Time (ไม่เกิน 1000 ms)
pm.test("[Performance] Page response time is under 1000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

// 3. ตรวจสอบ Header Content-Type ว่าส่งมาเป็น HTML หรือไม่
pm.test("[Header] Content-Type is text/html", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("text/html");
});

// 4. แปลงข้อความทั้งหมดเป็นตัวเล็กก่อนตรวจเช็ค (.toLowerCase())
const responseText = pm.response.text().toLowerCase();

pm.test("[UI Content] HTML contains Title or Core Keyword", function () {
    pm.expect(responseText).to.include("futureskill");
});

// 1. ตรวจสอบว่าไฟล์ Asset โหลดได้ปกติ ไม่เป็น 404 Not Found
pm.test("[Asset] Static asset loads successfully", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 304]);
});

// 2. ตรวจสอบความเร็วการโหลดไฟล์และแสดงผลข้อมูล
pm.test("[Performance] Asset response time is under 500ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(500);
});

// ตรวจสอบว่าการป้องกันสำหรับผู้เยี่ยมชมได้รับการจัดการอย่างถูกต้อง
pm.test("[Security] Guest access to protected page is handled correctly (404 Not Found)", function () {
    pm.expect(pm.response.code).to.be.oneOf([404]);
});

// 1. แปลง Response ที่ได้จาก Server ให้อยู่ในรูปแบบ JSON Object
const jsonData = pm.response.json();

// 2. ตรวจสอบว่า Response มี Token ส่งกลับมาจริงไหม
pm.test("Response contains access token", function () {
    // ปรับเปลี่ยน path ให้ตรงตาม Response ของจริง
    pm.expect(jsonData).to.have.property("accessToken"); 
});

// 3. บันทึก Token ลงใน Environment Variable อัตโนมัติ
if (jsonData.accessToken) {
    pm.environment.set("authToken", jsonData.accessToken);
    console.log("authToken updated successfully!");
}

if (jsonData.refreshToken) {
    pm.environment.set("refreshToken", jsonData.refreshToken);
}

// 1. ตรวจสอบว่า Status Code เป็น 403 Forbidden (หรือรวม 400, 401, 403)
pm.test("Status code - Should be 403 Forbidden", function () {
    pm.expect(pm.response.code).to.be.oneOf([400, 401, 403]);
});

// 2. แปลง Response เป็น JSON
const jsonData = pm.response.json();

// 3. ตรวจสอบว่า "ต้องไม่มี" Token ส่งกลับมา
pm.test("Verify security - Should NOT return access token", function () {
    pm.expect(jsonData).to.not.have.property("accessToken");
    pm.expect(jsonData).to.not.have.property("token");
});

// 4. ตรวจสอบข้อความแจ้งเตือน Error ภาษาไทย
pm.test("Verify error response - Should return error message", function () {
    const errorMessage = jsonData.message || jsonData.error || jsonData.description;
    pm.expect(errorMessage).to.be.a("string");
    
    // ตรวจเช็คการแจ้งเตือนข้อความคำว่า "กรอกรหัสผ่านไม่ถูกต้อง"
    pm.expect(errorMessage).to.include("กรอกรหัสผ่านไม่ถูกต้อง");
});

// 1. แปลง Response เป็น JSON
const jsonData = pm.response.json();

// 2. ตรวจสอบการ Profile update-name สำเร็จ (200 OK)
pm.test("[Status] Profile update-name successfully", function () {
    pm.response.to.have.status(200);
});

// 3. ตรวจสอบข้อความตอบกลับจากระบบ
pm.test("Verify success response message", function () {
    const message = jsonData.message || jsonData.error || jsonData.description;

    // เช็คประเภทข้อมูลตัวอักษร
    pm.expect(message).to.be.a("string");

    // เช็คเนื้อหาข้อความสำเร็จ
    pm.expect(message).to.include("success");
});
